package com.mfg.erp.controller;import com.mfg.common.api.ApiResponse;import com.mfg.erp.dto.SalesOrderCommand;import com.mfg.erp.entity.*;import com.mfg.erp.repo.*;import com.mfg.erp.service.SalesOrderService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/erp/sales-orders") @RequiredArgsConstructor public class SalesOrderController{private final SalesOrderRepository repo;private final SalesOrderLineRepository lines;private final SalesOrderService service;@GetMapping public ApiResponse<Page<SalesOrder>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(repo.findAll(PageRequest.of(Math.max(0,page-1),Math.min(size,200))));}@GetMapping("/{id}")public ApiResponse<Map<String,Object>> detail(@PathVariable Long id){SalesOrder o=repo.findById(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException());return ApiResponse.ok(Map.of("header",o,"lines",lines.findBySalesOrderNoOrderByLineNo(o.getSalesOrderNo())));}@PostMapping public ApiResponse<SalesOrder> create(@Valid @RequestBody SalesOrderCommand c){return ApiResponse.ok(service.create(c));}@PostMapping("/{id}/confirm")public ApiResponse<SalesOrder> confirm(@PathVariable Long id){return ApiResponse.ok(service.confirm(id));}}
